8	/* ---- Fonts ----
9	   Source Serif 4: Google Fonts (free).
10	   Futura Round: licensed. Files self-hosted in library/assets/Font Futura WOFF2/.
11	   NOTE (dev): these files must be served from a CDN in production.
12	   The Vercel deployment serves them automatically via the /library/:path* rewrite.
13	   For any other stack, upload the woff2 files to your CDN and update the src URLs below.
14	   FuturaRoundCond-* variants are present in assets but have no token mapping yet.
15	   --------------------------------------------------------- */
16	@import url('https://fonts.googleapis.com/css2?family=Source+Serif+4:ital,opsz,wght@0,8..60,400;0,8..60,500;1,8..60,400;1,8..60,500&display=swap');
