.zimm-text-mobile-body1 {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-regular);
  font-size: var(--zimm-font-size-2xs);
  line-height: var(--zimm-font-lineheight-2xs);
  letter-spacing: var(--zimm-font-letterspacing-sm);
}

.zimm-text-mobile-body2 {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-regular);
  font-size: var(--zimm-font-size-3xs);
  line-height: var(--zimm-font-lineheight-4xs);
  letter-spacing: var(--zimm-font-letterspacing-sm);
}


/* ---- Grid utility ---- */

.zimm-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  column-gap: 1px;
  padding-inline: var(--zimm-grid-margin-mobile);
}

@media (min-width: 768px) {
  .zimm-grid {
    grid-template-columns: repeat(8, 1fr);
    padding-inline: var(--zimm-grid-margin-tablet);
  }
}

@media (min-width: 1280px) {
  .zimm-grid {
    grid-template-columns: repeat(10, 1fr);
    padding-inline: var(--zimm-grid-margin-desktop);
  }
}


