===== ELEMENT JS HEADER COMMENTS (first 18 lines each) =====
----- 02-design/library/elements/add-to-wishlist/zimm-add-to-wishlist.js -----
const ASSETS = new URL('../icon/assets/', import.meta.url).href;

class ZimmAddToWishlist extends HTMLElement {
  static get observedAttributes() {
    return ['selected'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._onClick = this._onClick.bind(this);
  }

  connectedCallback() {
    this._render();
    this.shadowRoot.addEventListener('click', this._onClick);
  }


----- 02-design/library/elements/banner/zimm-banner.js -----
class ZimmBanner extends HTMLElement {
  static get observedAttributes() {
    return ['message', 'theme'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _dismiss() {
    this.style.display = 'none';
    this.dispatchEvent(new CustomEvent('zimm-banner-dismiss', { bubbles: true }));
  }


----- 02-design/library/elements/button/zimm-button.js -----
class ZimmButton extends HTMLElement {
  static get observedAttributes() {
    return ['variant', 'size', 'label', 'disabled', 'inverse', 'icon', 'type', 'full-width'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
